        "release_grants": (
            ("revoked_at", "DATETIME"),
        ),
        "trust_roots": (
            ("status", "VARCHAR(16)"),
            ("retired_at", "DATETIME"),
        ),
        "workload_identity_profiles": (
            ("status", "VARCHAR(16)"),
            ("updated_at", "DATETIME"),
            ("revoked_at", "DATETIME"),
        ),
        "workload_identity_claims": (
            ("seq", "INTEGER"),
        ),
